import React, { useState } from 'react';

type AsyncState<T> = {
  status: 'idle' | 'loading' | 'success' | 'error';
  data: T | null;
  error: string | null;
};

const App = () => {
  const [asyncState, setAsyncState] = useState<AsyncState<string>>({
    status: 'idle',
    data: null,
    error: null,
  });

  const fetchData = async (): Promise<string> => {
    await new Promise(resolve => setTimeout(resolve, 1000));
    return 'Data loaded!';
  };

  const handleFetch = async () => {
    setAsyncState({ status: 'loading', data: null, error: null });
    try {
      const result = await fetchData();
      setAsyncState({ status: 'success', data: result, error: null });
    } catch (err) {
      setAsyncState({ status: 'error', data: null, error: 'Failed to load data' });
    }
  };

  return (
    <div>
      {asyncState.status === 'idle' && <p>Click to load data</p>}
      {asyncState.status === 'loading' && <p>Loading...</p>}
      {asyncState.status === 'success' && <p>{asyncState.data}</p>}
      {asyncState.status === 'error' && <p>Error: {asyncState.error}</p>}
      {/* Add button with onClick handler here */}
    </div>
  );
};
